// ─── File: TokenLifecycleDemo.java ───
package com.bank.lifecycle;

import java.util.*;
import java.util.logging.*;

public class TokenLifecycleDemo {
    private static final Logger log = Logger.getLogger(TokenLifecycleDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthServer auth = new AuthServer();

        TokenPair first = auth.login("rajesh");
        log.info(() -> "Login: access=" + first.accessToken + " refresh=" + first.refreshToken);

        // Normal refresh: old refresh burned, new pair issued (rotation).
        TokenPair second = auth.refresh(first.refreshToken);
        log.info(() -> "Refreshed: new access=" + second.accessToken + " new refresh=" + second.refreshToken);

        // Thief reuses the OLD refresh token -> reuse detected, family revoked.
        try {
            auth.refresh(first.refreshToken);
        } catch (TokenReuseException e) {
            log.severe("REUSE DETECTED: " + e.getMessage() + " -> whole family revoked, re-login required");
        }

        // Now even the legitimate new refresh token is dead because the family was revoked.
        try {
            auth.refresh(second.refreshToken);
        } catch (TokenReuseException e) {
            log.warning("Legit token also revoked (family lockdown): " + e.getMessage());
        }
    }
}

// ─── Would be in TokenPair.java ───
class TokenPair {
    final String accessToken;
    final String refreshToken;
    TokenPair(String a, String r) { accessToken = a; refreshToken = r; }
}

// ─── Would be in RefreshRecord.java ───
class RefreshRecord {
    final String familyId;
    final String username;
    boolean used;
    boolean revoked;
        RefreshRecord(String familyId, String username) { this.familyId = familyId;
        this.username = username; }
}

// ─── Would be in TokenReuseException.java ───
class TokenReuseException extends RuntimeException {
    TokenReuseException(String m) { super(m); }
}

// ─── Would be in AuthServer.java ───
class AuthServer {
    // Map raw refresh token -> record (hash in production).
    private final Map<String, RefreshRecord> store = new HashMap<>();

    TokenPair login(String username) {
        String familyId = UUID.randomUUID().toString();
        return issuePair(username, familyId);
    }

    TokenPair refresh(String refreshToken) {
        RefreshRecord rec = store.get(refreshToken);
        if (rec == null) throw new TokenReuseException("unknown refresh token");
        if (rec.revoked) throw new TokenReuseException("refresh token revoked (family locked)");
        if (rec.used) {
            // A used token presented again = theft. Revoke the entire family.
            revokeFamily(rec.familyId);
            throw new TokenReuseException("refresh token already used (reuse detected)");
        }
        rec.used = true;                       // burn the old token (rotation)
        return issuePair(rec.username, rec.familyId);
    }

    private TokenPair issuePair(String username, String familyId) {
        String access = "acc-" + UUID.randomUUID();           // short-lived JWT in production
        String refresh = "ref-" + UUID.randomUUID();          // long-lived, server-tracked
        store.put(refresh, new RefreshRecord(familyId, username));
        return new TokenPair(access, refresh);
    }

    private void revokeFamily(String familyId) {
        for (RefreshRecord r : store.values())
            if (r.familyId.equals(familyId)) r.revoked = true;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
